import java.awt.*;import java.awt.image.*;import java.io.*;import java.util.*;import javax.imageio.ImageIO;import com.koios.client.arpg.*;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;import com.koios.game.arpg.*;import com.koios.game.model.item.Item;
/** Actual longest current equipment tooltips at viewport edges; later pixels must remain above source art. */
public final class TooltipBoundsCheck {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static BufferedImage canvas(int w,int h){BufferedImage im=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);int[] px=((DataBufferInt)im.getRaster().getDataBuffer()).getData();Arrays.fill(px,0x33403B);DrawingArea.initDrawingArea(h,w,px);return im;}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));Item worst=null;int longest=0;for(EquipmentBases.Base base:EquipmentBases.all())for(int seed=0;seed<50;seed++){Item i=EquipmentBases.create(base,30);java.util.List<ItemRoll.Affix> a=new ArrayList<>(AffixCatalog.roll(i,ItemRoll.Rarity.RARE,new Random(seed)));for(int n=1;n<=2;n++)a.add(new ItemRoll.Affix("corruption_"+n,ItemRoll.Layer.CORRUPTION_IMPLICIT,1,new Modifier(Stat.LIFE,Modifier.Operation.FLAT,10)));i.setRoll(i.getRoll().changed(ItemRoll.Rarity.RARE,true,2,a,null));int lines=ItemTooltip.lines(i,true).size();if(lines>longest){longest=lines;worst=i;}}
 ItemTooltipCache cache=new ItemTooltipCache();cache.accept(ItemTooltip.payload(3214,0,worst));ItemTooltipCache.Entry entry=cache.get(3214,0,worst.getId());for(int[] size:new int[][]{{512,334},{1280,720},{1920,1080}})for(int[] point:new int[][]{{0,0},{size[0]-1,0},{0,size[1]-1},{size[0]-1,size[1]-1}}){BufferedImage im=canvas(size[0],size[1]);ItemTooltipRenderer.draw(font,entry,true,point[0],point[1]);boolean outside=false;for(int y=0;y<size[1];y++)for(int x=0;x<size[0];x++)if((x<6||x>=size[0]-6||y<6||y>=size[1]-6)&&(im.getRGB(x,y)&0xFFFFFF)!=0x33403B)outside=true;check(!outside,"Tooltip remains inside viewport margins "+size[0]+" @"+Arrays.toString(point));if(point[0]>0&&point[1]>0)ImageIO.write(im,"png",new File("build/tooltip-bounds-"+size[0]+".png"));}
 canvas(512,334);ItemTooltipRenderer.Layout layout=ItemTooltipRenderer.layout(font,entry,true,511,333);check(layout.columns>1&&layout.lineHeight>=14,"Long fixed details use readable columns rather than compressed rows");check(20+(layout.rows-1)*layout.lineHeight<layout.height-4,"Every wrapped row fits without dropping text");check(String.join(" ",layout.lines).replaceAll("\\s+","").equals(String.join(" ",entry.advanced).replaceAll("\\s+","")),"All actual values, ranges and tier text survive layout");com.koios.game.model.player.Player p=PrototypeIntegrationCheck.player("statbounds",73);p.getArpgProgress().award(90000);p.getEquipment().set(3,worst);p.getArpgVitals().refill(p.getArpgStats());String[] sheet=CharacterSheet.lines(p).toArray(new String[0]);java.util.List<String> compact=CharacterPanel.rows(sheet);check(compact.size()==sheet.length-3,"All defence pairs compact without dropping unrelated fields");for(String line:compact)check(font.getTextWidth(line)<=172,"Actual compact stat row fits: "+line);check(42+(compact.size()-1)*14<254,"Every stat row remains visible with readable spacing");BufferedImage stats=canvas(240,300);CharacterPanel.draw(font,20,20,sheet);boolean spill=false;for(int y=0;y<300;y++)for(int x=0;x<240;x++)if((x<20||x>=210||y<20||y>=280)&&(stats.getRGB(x,y)&0xFFFFFF)!=0x33403B)spill=true;check(!spill,"Actual character sheet stays inside sidebar rectangle");ImageIO.write(stats,"png",new File("build/character-stats-bounds.png"));System.out.println("Passed "+checks+" tooltip/stat bounds checks; longest advanced current payload="+longest+" lines, wrapped="+layout.lines.size()+", line spacing="+layout.lineHeight+".");}}
}


